insert into collections(slug,name,theme,tagline,headline,description,variants_label,sanskrit,meaning,story,dial_color,sort) values
('dhruv','DHRUV','dhruv','The pole star that never moves','Stay true to your direction.','The pole star never moves. Our navy compass dial points the way.','3 watches','ध्रुव','Dhruva · unmoving · the pole star','We began with a story every Indian child knows: the boy Dhruva, who sat in stillness until the heavens gave him a place that never moves. Navigators and sages have looked to that star ever since. We asked what a fixed star would look like on a wrist, and drew an embossed compass rose that points north, with the seven stars of the Saptarishi, the sages whose pointer stars lead the eye to Dhruva. We chose navy for the hour just after sunset, when the sky is deepest and the first star appears. DHRUV is for people who stay true to their direction.','Navy',1),
('surya','SURYA','surya','The sun, in twelve rays','Carry your own light.','Twelve rays for twelve Adityas, gold on black.','5 watches','सूर्य','Surya · the sun, giver of light','The Vedas open many of their hymns to Surya, the sun that wakes the world each morning. Tradition names twelve Adityas, twelve forms of the sun, one for each month. We gave the dial twelve raised rays, six straight for steady light and six wavy for heat, alternating around a gold disc. We set it on black because we wanted the sun to look the way it does in the real sky: a single source of light in a very large dark. SURYA is for people who carry their own light.','Black',2),
('naksh','NAKSH','naksh','The 27 stars of the moon''s path','Some things are written.','Twenty-seven embossed stars on deep maroon, one for each night of the moon''s path.','4 watches','नक्श','Naksh · a mark, an imprint · echoing the 27 nakshatras','The ancient sky-watchers divided the moon''s path into 27 nakshatras, one resting place for each night of its journey. We placed all twenty-seven as embossed eight-point stars in a perfect ring, beginning with Ashwini at the top, around a quiet gold hub. Naksh means a mark, an imprint, and that is what we wanted this dial to be: a pattern that stays. We chose maroon, the colour of ritual, festival and long evenings. NAKSH is for people who believe some things are written.','Maroon',3),
('vyom','VYOM','vyom','The sky and its nine wanderers','Keep looking up.','Nine bodies, three orbits and a sphere, in gold on dark green.','4 watches','व्योम','Vyom · the sky, space, the open ether','Vyom is the open sky, the ether that holds everything. The Vedic astronomers followed nine celestial bodies, the Navagraha: the sun, the moon, the five visible planets and the two lunar nodes. We drew them as nine gold beads on orbit rings around a striated sphere, so the whole sky reads like an instrument on your wrist. We chose dark green for the depth of the sky seen through leaves after rain. VYOM is for people who still look up.','Dark green',4),
('soma','SOMA','soma','The moon in thirty tithis','Calm, in cycles.','Thirty lunar days around a silver crescent, on moonlit graphite.','4 watches','सोम','Soma · the moon, and the luminous drink of the Vedas','The Rigveda gives an entire book to Soma, the moon and the luminous drink of the gods. The lunar month is counted in thirty tithis, fifteen as the moon grows and fifteen as it fades. We set thirty dots in a ring, fifteen bright and fifteen dark, around a hammered silver crescent. We used graphite for moonlit stone, and silver only, no gold, because the moon has none. SOMA is for people who find calm in cycles.','Graphite',5)
on conflict (slug) do nothing;

insert into products(slug,name,sku,collection_id,tagline,description,long_description,features,case_color,strap_color,weight_g,price,compare_price,stock,edition_total,edition_sold,featured,specs,sort,seo_title,seo_description)
select 'dhruv-night','Dhruv Night','YG-DHR-BK-BK',(select id from collections where slug='dhruv'),'Set by the pole star. Cast in black.','Black tonneau case, black silicone strap and an embossed navy compass dial, powered by Japanese quartz.','A 44 × 52 mm black case sets off a deep navy sunray dial. Raised gold markers, a compass rose and the Saptarishi stars sit above the surface, with a red seconds hand and gold hands that stay readable in any light. The soft black silicone strap is moulded to the case, so it sits flush and light on the wrist. Accurate Japanese quartz movement and a 1-year warranty.','["Embossed navy dial with raised gold detail", "Japanese quartz movement", "Black tonneau case, Black silicone strap", "44 × 52 mm, 15 mm thick", "1-year warranty"]'::jsonb,'Black','Black',85,5999,9999,50,0,0,true,'{"Movement": "Japanese quartz", "Case": "Black, tonneau, 44 × 52 mm, 17 mm thick", "Strap": "Black silicone", "Dial": "Embossed navy dial", "Weight": "Approx. 85 g", "Warranty": "1 year"}'::jsonb,1,'Dhruv Night | YUGASTRA Dhruv Collection','Black tonneau case, black silicone strap and an embossed navy compass dial, powered by Japanese quartz. Japanese quartz, silicone strap, 1-year warranty. ₹5,999.'
on conflict (slug) do nothing;
