select 'soma-crescent','Soma Crescent','YG-SOM-SL-BK',(select id from collections where slug='soma'),'Thirty lunar days, one silver crescent.','Silver tonneau case, black silicone strap and an embossed graphite moon dial, powered by Japanese quartz.','A hammered silver crescent and a ring of thirty dots, fifteen bright and fifteen dark, on a radial-brushed graphite dial. The silver case is 44 × 52 mm and the black silicone strap is soft and light. Silver hands with white lume, Japanese quartz movement, 1-year warranty.','["Embossed graphite dial with raised silver detail", "Japanese quartz movement", "Silver tonneau case, Black silicone strap", "44 × 52 mm, 15 mm thick", "1-year warranty"]'::jsonb,'Silver','Black',85,5999,9999,50,0,0,true,'{"Movement": "Japanese quartz", "Case": "Silver, tonneau, 44 × 52 mm, 17 mm thick", "Strap": "Black silicone", "Dial": "Embossed graphite dial", "Weight": "Approx. 85 g", "Warranty": "1 year"}'::jsonb,17,'Soma Crescent | YUGASTRA Soma Collection','Silver tonneau case, black silicone strap and an embossed graphite moon dial, powered by Japanese quartz. Japanese quartz, silicone strap, 1-year warranty. ₹5,999.'
