insert into site_settings(key,value) values ('ticker','"The weapon of timelessness ✦ Time, written in the sky ✦ Made to outlast the hour ✦ कालजयी · समय से परे ✦ A piece to keep"') on conflict (key) do update set value=excluded.value;
update collections set tagline='The realm of stillness',headline='Be the fixed point.',description='A navy dial, a compass rose, the seven sages. The pole star, made to be worn.',story='Dhruva was a boy who sat in stillness until the heavens gave him a place that never moves. Every sailor and sage since has steered by that star. We asked what a fixed point would look like on the wrist, and drew a compass rose in raised gold, with the seven stars of the Saptarishi leading the eye to north. The dial is navy, the hour just after sunset when the first star appears. DHRUV is the realm of stillness: for those who stay true to their direction while the world turns around them. It is the first watch of the first age, and the one that never loses its bearing.' where slug='dhruv';
update collections set tagline='The realm of light',headline='Carry your own light.',description='Twelve rays for twelve Adityas, in gold on black. One sun, worn.',story='The Vedas open their hymns to Surya, the sun that wakes the world. Tradition counts twelve Adityas, twelve forms of the sun, one for every month. We gave the dial twelve raised rays, six straight for steady light and six wavy for heat, alternating around a gold disc. We set it on black because the sun in the real sky is a single source of light in a very large dark. SURYA is the realm of light: for those who do not wait to be lit, and who carry their own radiance into every room.' where slug='surya';
update collections set tagline='The realm of destiny',headline='Some things are written.',description='Twenty-seven embossed stars on deep maroon, one for every night of the moon''s path.',story='The ancient sky-watchers divided the moon''s path into twenty-seven nakshatras, one resting place for each night of its journey. We set all twenty-seven as raised eight-point stars in an unbroken ring, beginning with Ashwini at the top, around a quiet gold hub. Naksh means a mark, an imprint, and that is the intention: a pattern that stays. The dial is maroon, the colour of ritual, festival and long evenings. NAKSH is the realm of destiny: for those who believe some things are written, and who wear the proof.' where slug='naksh';
update collections set tagline='The realm of space',headline='Keep looking up.',description='Nine graha on three orbits around a sphere, in gold on deep green.',story='Vyom is the open sky, the ether that holds everything. The Vedic astronomers followed nine bodies, the Navagraha: the sun, the moon, the five visible planets and the two lunar nodes. We drew them as nine gold beads on orbit rings around a striated sphere, so that the whole sky reads as an instrument on the wrist. The dial is deep green, the sky seen through leaves after rain. VYOM is the realm of space: for those who still look up, and who understand that depth is a form of luxury.' where slug='vyom';
update collections set tagline='The realm of rhythm',headline='Calm, in cycles.',description='Thirty lunar days around a hammered silver crescent, on moonlit graphite.',story='The Rigveda gives an entire book to Soma, the moon and the luminous drink of the gods. The lunar month is counted in thirty tithis, fifteen as the moon grows and fifteen as it fades. We set thirty dots in a ring, fifteen bright and fifteen dark, around a hammered silver crescent. The dial is graphite, moonlit stone, and the detail is silver only, because the moon has no gold. SOMA is the realm of rhythm: for those who find calm in cycles, and trust that everything returns in its own time.' where slug='soma';
update products set tagline='Constancy, in black.',description='Stillness at its darkest. Black case, black strap, an embossed navy compass dial. Japanese quartz.',long_description='Stillness at its darkest. A black case holds a deep navy dial, where a compass rose and the seven sages stand in raised gold, as quiet and as certain as the star they follow. A black tonneau case, 44 × 52 mm and 17 mm deep, with a deep and even finish. The black silicone strap is soft, light and moulded to sit flush against the case. Within is an accurate Japanese quartz movement. Dhruv Night belongs to Dhruv, one realm of the Yugastra sky: a timeless piece, made to be kept and not replaced.',features='["Embossed navy dial with raised gold detail", "Japanese quartz movement", "Black tonneau case, Black silicone strap", "44 × 52 mm, 17 mm deep", "1-year warranty"]'::jsonb,specs='{"Movement": "Japanese quartz", "Case": "Black, tonneau, 44 × 52 mm, 17 mm deep", "Strap": "Black silicone", "Dial": "Embossed navy dial", "Weight": "Approx. 85 g", "Warranty": "1 year"}'::jsonb,seo_title='Dhruv Night · Dhruv Collection | YUGASTRA',seo_description='Constancy, in black. Dhruv Night: black case, black strap, an embossed navy compass dial. Japanese quartz, 1-year warranty. From YUGASTRA, the weapon of timelessness. ₹5,999.' where slug='dhruv-night';
update products set tagline='The seven sages point north.',description='Silver and blue, the cold clear air before dawn. Silver case, blue strap, an embossed navy compass dial. Japanese quartz.',long_description='Silver and blue, the cold clear air before dawn. A polished silver case frames the navy compass dial, and a deep blue strap keeps the same true heading. A polished silver tonneau case, 44 × 52 mm and 17 mm deep, bright as moonlight on water. The blue silicone strap is soft, light and moulded to sit flush against the case. Within is an accurate Japanese quartz movement. Dhruv North belongs to Dhruv, one realm of the Yugastra sky: a timeless piece, made to be kept and not replaced.',features='["Embossed navy dial with raised gold detail", "Japanese quartz movement", "Silver tonneau case, Blue silicone strap", "44 × 52 mm, 17 mm deep", "1-year warranty"]'::jsonb,specs='{"Movement": "Japanese quartz", "Case": "Silver, tonneau, 44 × 52 mm, 17 mm deep", "Strap": "Blue silicone", "Dial": "Embossed navy dial", "Weight": "Approx. 85 g", "Warranty": "1 year"}'::jsonb,seo_title='Dhruv North · Dhruv Collection | YUGASTRA',seo_description='The seven sages point north. Dhruv North: silver case, blue strap, an embossed navy compass dial. Japanese quartz, 1-year warranty. From YUGASTRA, the weapon of timelessness. ₹5,999.' where slug='dhruv-north';
update products set tagline='A fixed star, worn in gold.',description='The pole star as it would look if it could be held. Gold case, brown strap, an embossed navy compass dial. Japanese quartz.',long_description='The pole star as it would look if it could be held. Warm gold surrounds a deep navy dial, and a brown strap grounds it, the earth beneath the sky. A warm gold tonneau case, 44 × 52 mm and 17 mm deep, a soft champagne in colour, never loud. The brown silicone strap is soft, light and moulded to sit flush against the case. Within is an accurate Japanese quartz movement. Dhruv Star belongs to Dhruv, one realm of the Yugastra sky: a timeless piece, made to be kept and not replaced.',features='["Embossed navy dial with raised gold detail", "Japanese quartz movement", "Gold tonneau case, Brown silicone strap", "44 × 52 mm, 17 mm deep", "1-year warranty"]'::jsonb,specs='{"Movement": "Japanese quartz", "Case": "Gold, tonneau, 44 × 52 mm, 17 mm deep", "Strap": "Brown silicone", "Dial": "Embossed navy dial", "Weight": "Approx. 85 g", "Warranty": "1 year"}'::jsonb,seo_title='Dhruv Star · Dhruv Collection | YUGASTRA',seo_description='A fixed star, worn in gold. Dhruv Star: gold case, brown strap, an embossed navy compass dial. Japanese quartz, 1-year warranty. From YUGASTRA, the weapon of timelessness. ₹5,999.' where slug='dhruv-star';
update products set tagline='The sun, held in shadow.',description='Black on black, with only the gold remaining. Black case, black strap, an embossed gold sun on a black dial. Japanese quartz.',long_description='Black on black, with only the gold remaining. It is the moment of totality, when the sun is hidden and every one of its twelve rays is still there. A black tonneau case, 44 × 52 mm and 17 mm deep, with a deep and even finish. The black silicone strap is soft, light and moulded to sit flush against the case. Within is an accurate Japanese quartz movement. Surya Eclipse belongs to Surya, one realm of the Yugastra sky: a timeless piece, made to be kept and not replaced.',features='["Embossed black dial with twelve raised gold rays", "Japanese quartz movement", "Black tonneau case, Black silicone strap", "44 × 52 mm, 17 mm deep", "1-year warranty"]'::jsonb,specs='{"Movement": "Japanese quartz", "Case": "Black, tonneau, 44 × 52 mm, 17 mm deep", "Strap": "Black silicone", "Dial": "Embossed black dial", "Weight": "Approx. 85 g", "Warranty": "1 year"}'::jsonb,seo_title='Surya Eclipse · Surya Collection | YUGASTRA',seo_description='The sun, held in shadow. Surya Eclipse: black case, black strap, an embossed gold sun on a black dial. Japanese quartz, 1-year warranty. From YUGASTRA, the weapon of timelessness. ₹5,999.' where slug='surya-eclipse';
update products set tagline='One sun. Twelve rays. In gold.',description='The sun at full strength. Gold case, black strap, an embossed gold sun on a black dial. Japanese quartz.',long_description='The sun at full strength. A gold case around a black dial and its twelve raised rays, finished with a black strap so that all the light stays at the centre. A warm gold tonneau case, 44 × 52 mm and 17 mm deep, a soft champagne in colour, never loud. The black silicone strap is soft, light and moulded to sit flush against the case. Within is an accurate Japanese quartz movement. Surya Radiance belongs to Surya, one realm of the Yugastra sky: a timeless piece, made to be kept and not replaced.',features='["Embossed black dial with twelve raised gold rays", "Japanese quartz movement", "Gold tonneau case, Black silicone strap", "44 × 52 mm, 17 mm deep", "1-year warranty"]'::jsonb,specs='{"Movement": "Japanese quartz", "Case": "Gold, tonneau, 44 × 52 mm, 17 mm deep", "Strap": "Black silicone", "Dial": "Embossed black dial", "Weight": "Approx. 85 g", "Warranty": "1 year"}'::jsonb,seo_title='Surya Radiance · Surya Collection | YUGASTRA',seo_description='One sun. Twelve rays. In gold. Surya Radiance: gold case, black strap, an embossed gold sun on a black dial. Japanese quartz, 1-year warranty. From YUGASTRA, the weapon of timelessness. ₹5,999.' where slug='surya-radiance';
update products set tagline='The first light, kept.',description='Gold and warm brown, the colours of the first hour of the morning on the earth. Gold case, brown strap, an embossed gold sun on a black dial. Japanese quartz.',long_description='Gold and warm brown, the colours of the first hour of the morning on the earth. A watch for those who begin early, and begin well. A warm gold tonneau case, 44 × 52 mm and 17 mm deep, a soft champagne in colour, never loud. The brown silicone strap is soft, light and moulded to sit flush against the case. Within is an accurate Japanese quartz movement. Surya Sunrise belongs to Surya, one realm of the Yugastra sky: a timeless piece, made to be kept and not replaced.',features='["Embossed black dial with twelve raised gold rays", "Japanese quartz movement", "Gold tonneau case, Brown silicone strap", "44 × 52 mm, 17 mm deep", "1-year warranty"]'::jsonb,specs='{"Movement": "Japanese quartz", "Case": "Gold, tonneau, 44 × 52 mm, 17 mm deep", "Strap": "Brown silicone", "Dial": "Embossed black dial", "Weight": "Approx. 85 g", "Warranty": "1 year"}'::jsonb,seo_title='Surya Sunrise · Surya Collection | YUGASTRA',seo_description='The first light, kept. Surya Sunrise: gold case, brown strap, an embossed gold sun on a black dial. Japanese quartz, 1-year warranty. From YUGASTRA, the weapon of timelessness. ₹5,999.' where slug='surya-sunrise';
