update products set tagline='Twenty-seven embers, glowing.',description='A black case with a maroon strap, the stars like coals in a banked fire. Black case, maroon strap, an embossed maroon dial with twenty-seven stars. Japanese quartz.',long_description='A black case with a maroon strap, the stars like coals in a banked fire. Warm, low and enduring. A black tonneau case, 44 × 52 mm and 17 mm deep, with a deep and even finish. The maroon silicone strap is soft, light and moulded to sit flush against the case. Within is an accurate Japanese quartz movement. Naksh Ember belongs to Naksh, one realm of the Yugastra sky: a timeless piece, made to be kept and not replaced.',features='["Embossed maroon dial with 27 raised stars", "Japanese quartz movement", "Black tonneau case, Maroon silicone strap", "44 × 52 mm, 17 mm deep", "1-year warranty"]'::jsonb,specs='{"Movement": "Japanese quartz", "Case": "Black, tonneau, 44 × 52 mm, 17 mm deep", "Strap": "Maroon silicone", "Dial": "Embossed maroon dial", "Weight": "Approx. 85 g", "Warranty": "1 year"}'::jsonb,seo_title='Naksh Ember · Naksh Collection | YUGASTRA',seo_description='Twenty-seven embers, glowing. Naksh Ember: black case, maroon strap, an embossed maroon dial with twenty-seven stars. Japanese quartz, 1-year warranty. From YUGASTRA, the weapon of timelessness. ₹5,999.' where slug='naksh-ember';
